/bin/bash -lc "python - <<'PY'
import sim
s=sim.Sim()
print('all bodies')
for i in range(s.model.nbody):
    n=sim.mujoco.mj_id2name(s.model, sim.mujoco.mjtObj.mjOBJ_BODY,i)
    if n:
        if 'panda' in n or 'hand' in n or 'finger' in n or 'cup' in n or 'table' in n:
            print(i,n,s.data.xpos[i])
print('all geoms with names')
for i in range(s.model.ngeom):
    n=sim.mujoco.mj_id2name(s.model, sim.mujoco.mjtObj.mjOBJ_GEOM,i)
    if n and ('panda' in n or 'cup' in n or 'table' in n or 'finger' in n):
        print(i,n,s.data.geom_pos[i], s.model.geom_size[i])
print('geom range',s.model.ngeom)
PY"

